\label{ns_max}
Fix an integer $d\ge1$.
Let $Z_1,\ldots,Z_n$ be jointly Gaussian with standard normal
marginals, and suppose that
\begin{align}\label{ns_rows}
 \max_{1\le i\le n}
 \sum_{j=1}^n|\mathbb{E}[Z_iZ_j]|^d\le K<\infty.
\end{align}
For every $f\in L^2(\gamma)$ with Hermite rank at least $d$,
\begin{align}\label{ns_l2}
 \mathbb{E}\left[\max_{0\le m\le n}
 \left|\sum_{k=1}^m f(Z_k)\right|^2\right]
 \le C_{d,K}n\|f\|_2^2.
\end{align}
More generally, for every $2<p<\infty$ and every
$f\in L^p(\gamma)$ with Hermite rank at least $d$,
\begin{align}\label{ns_bdd}
 \left\|\max_{0\le m\le n}
 \left|\sum_{k=1}^m f(Z_k)\right|\right\|_p
 \le C_{p,d,K}\sqrt n\,\|f\|_p.
\end{align}

\label{ns_int}
Fix an integer $d\ge1$.  Let $Y=(Y(s))_{s\ge0}$ be a jointly
measurable Gaussian process with standard normal marginals.
Suppose that there is some $K<\infty$ such that
\begin{align}\label{ns_fib}
 \sup_{u\in[0,1]}\sup_{i\in\{0,1,\ldots\}}
 \sum_{j=0}^{\infty}
 \big|\mathbb{E}[Y(1+u+i)Y(1+u+j)]\big|^d\le K.
\end{align}
For $g\in L^2(\gamma)$ with Hermite rank at least $d$, define
\begin{align}\label{int_proc}
 F_\varepsilon^g(t)=\sqrt\varepsilon\int_0^{t/\varepsilon}g(Y(s))\,ds,
 \quad t\ge0.
\end{align}
These processes have almost surely continuous paths and satisfy
\begin{align}\label{ns_intbd}
 \sup_{0<\varepsilon\le1}
 \mathbb{E}\left[\sup_{t\in[0,1]}|F_\varepsilon^g(t)|^2\right]
 \le C_{d,K}\|g\|_2^2.
\end{align}
For $f,g\in L^2(\gamma)$ such that $f-g$ has Hermite rank at least
$d$, the same estimate holds for $F_\varepsilon^f-F_\varepsilon^g$, with
$\|f-g\|_2^2$ on the right-hand side.

\label{ss_thm}
Let $X$ be the self-similar Gaussian process as above, satisfying
\textup{\bf(H.1)}--\textup{\bf(H.2)}, and let $\varphi\in L^2(\gamma)$ have
Hermite rank $d\geq 1$
as in
\eqref{d_phi}.  Suppose that
$\alpha<2- \frac{1}{d}$.  Then
\begin{align}\label{ss_fclt}
 \widetilde F_\varepsilon^\varphi\Longrightarrow\sigma_{\varphi,\alpha}\mathcal{W}
 \quad\text{in }\mathbf{C}([0,1]),\quad \varepsilon\downarrow0,
\end{align}
where $\mathcal{W}$ is standard Brownian motion and
\begin{align}\label{ss_var}
 \sigma_{\varphi,\alpha}^2
 =\sum_{q=d}^{\infty}q!c_q^2
   \int_\mathbb{R} a_\alpha(h)^q\,dh\in[0,\infty).
\end{align}
The same conclusion holds for $F_\varepsilon^\varphi$.

\label{ss_crit}
Let $X$ satisfy \textup{\bf(H.1)}--\textup{\bf(H.2)} as above,
let $\varphi\in L^2(\gamma)$ have expansion \eqref{d_phi}, and suppose that
$\alpha=2- \frac{1}{d}$.  Then
\begin{align}\label{crit_fclt}
 \frac{\widetilde F_\varepsilon^\varphi}{\sqrt{\log(1/\varepsilon)}}
 \Longrightarrow\sigma_*\mathcal{W}
 \quad\text{in }\mathbf{C}([0,1]),\quad \varepsilon\downarrow0,
\end{align}
where
\begin{align}\label{crit_var}
 \sigma_*^2=2d!c_d^2
 \left(\frac{\alpha(\alpha-1)}{2}\right)^d =   2d!c_d^2
 \left(\frac{(2d-1)(d-1)}{2d^2}\right)^d.
\end{align}
The same conclusion holds for $F_\varepsilon^\varphi$.
When $d=1$, the limit is the zero process.

\label{max_lem}
Let  $X_1,\ldots,X_N$ be centered random variables.  For an integer
interval $I\subset\{1,\ldots,N\}$, write $S_I=\sum_{i\in I}X_i$.
Suppose that
\begin{align}
 \mathbb{E}[S_I^2]&\le C_0|I|,\label{abs_var}\\
 \mathbb{E}[S_I^2S_J^2]&\le C_1N^{1-\alpha}
 (|I|+|J|)^{1+\alpha}\label{abs_adj}
\end{align}
for all $I$ and all adjacent disjoint $I,J$ {\rm(}as illustrated in Figure \ref{fig_adj}{\rm)},
 where $\alpha>0$.
Then
\begin{align}\label{abs_max}
 \mathbb{E}\left[
  \max_{0\le m\le N}
  \left|\sum_{k=1}^mX_k\right|^2
 \right]\le C_{\alpha,C_0,C_1}N.
\end{align}

\label{lp_block}
Under \eqref{ns_rows}, for $p>2$, every $f\in L^p(\gamma)$ of
Hermite rank at least $d$, and every index set
$I\subset\{1,\ldots,n\}$,
we have 

\noindent
\begin{align}\label{lp_block_bd}
 \left\|\sum_{i\in I}f(Z_i)\right\|_p
 \le C_{p,d}\sqrt{K|I|}\,\|f\|_p.
\end{align}

\label{com_lem}
Let $N=2^L$ for an integer $L\ge0$.
For each dyadic length $\ell\in\{1,2,4,\ldots,N\}$, define
\begin{align}\label{com_part}
 \mathcal D_\ell
 =
 \left\{
 \{j\ell+1,\ldots,(j+1)\ell\}:
 j=0,\ldots,\frac{N}{\ell}-1
 \right\}.
\end{align}
Thus $\mathcal D_\ell$ partitions $\{1,\ldots,N\}$ into
$N/\ell$ intervals of length $\ell$.

Every initial segment $\{1,\ldots,m\}$, $0\le m\le N$,
is a disjoint union of canonical dyadic intervals, with
at most one interval from each $\mathcal D_\ell$.
Consequently, for arbitrary real numbers $x_1,\ldots,x_N$,
\begin{align}\label{use2a}
 \max_{0\le m\le N}
 \left|\sum_{k=1}^m x_k\right|
 \le
 \sum_{\substack{\ell\le N\\ \ell\ {\rm dyadic}}}
 \max_{D\in\mathcal D_\ell}
 \left|\sum_{k\in D}x_k\right|.
\end{align}

\label{sq_lem}
Fix $M<\infty$ and assume $\|\varphi\|_2\le M$.
Recall $B_{q,n}$ and $\mathcal H_n$ from \eqref{sq_dec}.
  For $1\le q<d$, we have
\begin{align}\label{sq_low}
  \|B_{q,n}\|_2 = \big|  \mathbb{E}[ g_n^2(\mathcal Z) h_q(\mathcal Z)] \big|
  \le C_q(1+\log n)^{q/2}.
\end{align}
Moreover,
\begin{align}\label{high_l2}
  \|\mathcal H_n\|_2^2\le Cn.
\end{align}

\noindent
Fix $0<\varepsilon<1$ and put  $\theta=\frac{2\varepsilon}{1+\varepsilon}<1$.
Then,
there exists $C=C_{d,M,\varepsilon}<\infty$ such that
for $|r|\le\varepsilon$,

\noindent
\begin{align}\label{sq_high}
  \sum_{q\ge d} \| B_{q,n}\|_2^2|r|^q
  \le Cn^\theta|r|^d.
\end{align}
The above constants are uniform over $\|\varphi\|_2\le M$ for each
fixed $M<\infty$.

\label{adj_prop}
Under the preceding assumptions, suppose $\|\varphi\|_2\le M$.
Then the following statements hold.

\smallskip

{\rm (i)} $\mathbb{E}[S_I^2]\le KM^2|I|$ for every interval $I$.

\smallskip

{\rm (ii)}
There exist $\alpha \in(0, \frac{1}{4d}]$ and $C<\infty$, depending only on
$(d,\varepsilon,K,A_0,  M)$
such that
\begin{align}\label{adj_bd}
 \mathbb{E}[S_I^2S_J^2]\le CN^{1-\alpha} ( |I| + |J| )^{1+\alpha}
\end{align}
for any adjacent disjoint integer intervals
$I,J\subset\{1,\ldots,N\}$.

\label{small_support}
Assume \eqref{ns_rows}.  Let $u\in L^2(\gamma)$ vanish outside a
measurable set $A$ with $\gamma(A)\leq 1/ n$.  Then
\begin{align}\label{small_support_bd}
 \mathbb{E}\bigg[ \Big(\sum_{k=1}^n|u(Z_k)|\Big)^2 \bigg]
 \le C_{d,K}n\|u\|_2^2.
\end{align}
In particular, 
\begin{align}\label{bd_MA}
\mathbb{E}\bigg[ \max_{m\le n} \Big|\sum_{k=1}^m u(Z_k)\Big|^2 \bigg]
 \leq  C_{d,K}n\|u\|_2^2.
 \end{align}

We first prove \eqref{ns_l2} when distinct coordinates have
small correlations, then remove this restriction by a partition
argument.  The cases $f=0$ and $n=1$ are immediate.
By homogeneity, we may otherwise assume $\|f\|_2=1$ and $n\ge2$.

\smallskip
$\bullet$  \textbf{Separated case.}
First assume\footnote{The choice $\delta=\frac{1}{8}$ is a
convenient fixed small number less than $\frac{1}{3}$,
as required by \eqref{small_c1}.}
\begin{align}\label{assump_31}
 |\mathbb{E}[Z_iZ_j]|\le\delta=\frac{1}{8},
 \quad i\ne j.
\end{align}
As in \eqref{trunc_def}--\eqref{g_def}, define
\begin{align*}
 T_n=f\mathbf{1}_{\{|f|\le\sqrt n\}}
 \quad{\rm and}\quad
 g_n=T_n-\sum_{q<d}\beta_{q,n}h_q,
\end{align*}
where $\beta_{q,n}=\langle T_n,h_q\rangle_{L^2(\gamma)}$.
The estimates in Sections~\ref{clip}--\ref{square} give
\begin{align}\label{ns_clip}
 \begin{aligned}
 &\|g_n\|_2\le1,\quad \|g_n\|_4^4\le C_dn,
   \quad |\beta_{0,n}|\le n^{-\frac{1}{2}},\\
 &|\beta_{q,n}|
   \le C_qn^{-\frac{1}{2}}(1+\log n)^{\frac{q}{2}},
   \quad 1\le q<d.
 \end{aligned}
\end{align}
The Gaussian vector $(Z_1,\ldots,Z_n)$ satisfies the hypotheses
of Proposition~\ref{adj_prop} with $N=n$, $A_0=M=1$,
and $\varepsilon=\delta = 1/8$.
Thus Proposition~\ref{adj_prop} and Lemma~\ref{max_lem} yield
\begin{align}\label{ns_gmax}
 \mathbb{E}\max_{0\le m\le n}
 \left|\sum_{k=1}^m g_n(Z_k)\right|^2
 \le C_{d,K}n.
\end{align}

\smallskip
$\bullet$
\textbf{Restoration in $L^2$: Step~\eqref{step_restore}.}
  Put
$E_n=\{|f|>\sqrt n\}$ and
$\tau_n=\|f\mathbf{1}_{E_n}\|_2\le1$.
Since $\gamma(E_n)\leq 1/n$,
Lemma~\ref{small_support} gives
\begin{align}\label{ns_tail}
 \left\|\max_{0\le m\le n}
 \left|\sum_{k=1}^m(f-T_n)(Z_k)\right|\right\|_2
 \le C_{d,K}\sqrt n\,\tau_n.
\end{align}
Next, let $P_n=\sum_{q<d}\beta_{q,n}h_q$ as before.
We claim that
\begin{align}\label{12d}
 \left\|\max_{0\le m\le n}
 \left|\sum_{k=1}^mP_n(Z_k)\right|\right\|_2
 \le C_{d,K}\sqrt n\,\tau_n.
\end{align}
Since the low Hermite coefficients of $f$ vanish,
$\beta_{q,n}=-\langle f\mathbf{1}_{E_n},h_q\rangle$.
Thus $n|\beta_{0,n}|\le\sqrt n\,\tau_n$.
For $d\ge2$ and $1\le q<d$, the small-set calculation \eqref{small_cal}
in the proof of Lemma~\ref{small_support} gives
\begin{align}\label{restore_coef}
 |\beta_{q,n}|
 \le\tau_n
 \left(\int_{E_n}h_q^2\,d\gamma\right)^{\frac{1}{2}}
  \leq \tau_n  \| h_q\|_{2d} \, \gamma(E_n)^{\frac{1}{2} - \frac{1}{2d}}
 \le C_d\tau_n n^{-\frac{1}{2}+\frac{1}{2d}}.
\end{align}
It remains to combine this with an $L^2$ maximal estimate
for   fixed   $1\leq q < d$.

Fix such a $q$.  By \eqref{OL_pq}, for every integer interval
$I\subset\{1,\ldots,n\}$ of cardinality $m$,
\begin{align}\label{ns_low}
 \mathbb{E}\left|\sum_{k\in I}h_q(Z_k)\right|^2
 \le\sum_{i,j\in I}|\mathbb{E}[Z_iZ_j]|^q
 \le K^{\frac{q}{d}}m^{2-\frac{q}{d}},
\end{align}
where the last inequality follows from H\"older's inequality
as in \eqref{corr_low}.
We now apply Lemma~\ref{com_lem} to obtain the required
low-chaos maximal estimate.
Let $n'$ be the smallest power of two with $n'\ge n$,
so that $n\le n'<2n$, and set
\begin{align*}
 X_k=
 \begin{cases}
  h_q(Z_k),&1\le k\le n,\\
  0,&n<k\le n'.
 \end{cases}
\end{align*}
Using the dyadic partitions $\mathcal D_\ell$ from
Lemma~\ref{com_lem} with $N=n'$,
we can obtain 

\noindent
\begin{align}\label{use2a2}
 \max_{0\le m\le n}
 \left|\sum_{k=1}^m h_q(Z_k)\right|
 \le
 \sum_{\substack{\ell\le n'\\ \ell\ {\rm dyadic}}}
 \max_{D\in\mathcal D_\ell}
  \Big| \sum_{k\in D}X_k   \Big|.
\end{align}
For each dyadic length $\ell$, there are $n' /\ell$
blocks in $\mathcal D_\ell$.
Since $D\cap\{1,\ldots,n\}$ is empty or an integer interval
of length at most $\ell$, \eqref{ns_low} yields
\begin{align*}
 \left\|
 \max_{D\in\mathcal D_\ell}
 \Big|  \sum_{k\in D}X_k \Big|
 \right\|_2^2
 &\le
 \sum_{D\in\mathcal D_\ell}
 \left\|\sum_{k\in D}X_k\right\|_2^2\\
 &\le
 K^{\frac{q}{d}}\frac{n'}{\ell}\,
 \ell^{2-\frac{q}{d}}
 \le Cn\,\ell^{1-\frac{q}{d}}.
\end{align*}
Here the first inequality follows from
$\max_a|U_a|^2\le\sum_a|U_a|^2$, and the last uses $n'<2n$.
Consequently,
\begin{align}\label{use2b}
 \left\|
 \max_{D\in\mathcal D_\ell}
 \Big|  \sum_{k\in D}X_k  \Big|
 \right\|_2
 \le C\sqrt n\,\ell^{\frac{1}{2}(1-\frac{q}{d})}.
\end{align}
Combining \eqref{use2a2} and \eqref{use2b}
with Minkowski's inequality gives
\begin{align}\label{ns_lowmax}
 \begin{aligned}
 \left\|  \max_{0\le m\le n}
 \Big|  \sum_{k=1}^m h_q(Z_k) \Big|   \right\|_2
 \leq
 C\sqrt n
 \sum_{\substack{\ell\le n'\\ \ell\ {\rm dyadic}}}
 \ell^{\frac{1}{2}(1-\frac{q}{d})} 
& \leq
 C_{d,K,q}\sqrt n\,
 (n')^{\frac{1}{2}(1-\frac{q}{d})} \\
 &\le C_{d,K,q}n^{1-\frac{q}{2d}}.  
 \end{aligned}
 \end{align}
The second inequality uses $q<d$, so the dyadic sum is
bounded by a constant times its largest term.

Combining \eqref{restore_coef} and \eqref{ns_lowmax},
we obtain
\begin{align*}
 |\beta_{q,n}|
 \left\|\max_{0\le m\le n}
 \Big|   \sum_{k=1}^m h_q(Z_k)  \Big|  \right\|_2
 &\le
 C\tau_n n^{-\frac{1}{2}+\frac{1}{2d}}
 n^{1-\frac{q}{2d}}\\
 &=C\tau_n n^{\frac{1}{2}-\frac{q-1}{2d}}
 \le C\sqrt n\,\tau_n.
\end{align*}
Summing over $1\le q<d$ and including the constant
correction proves \eqref{12d}.
When $d=1$, only the constant correction is present.
Since $f=g_n+(f-T_n)+P_n$, the  triangle inequality
and Minkowski's inequality, together with \eqref{ns_gmax},
\eqref{ns_tail}, and \eqref{12d}, give
\begin{align*}
 \left\|\max_{0\le m\le n}
 \left|\sum_{k=1}^m f(Z_k)\right|\right\|_2
 \le C_{d,K}\sqrt n(1+\tau_n)
 \le C_{d,K}\sqrt n.
\end{align*}
This proves \eqref{ns_l2} under \eqref{assump_31}.















\medskip
$\bullet$
\textbf{Finite partition and recombination:
Step~\eqref{step_partition}.}
We now remove \eqref{assump_31}.
Construct a graph on $\{1,\ldots,n\}$ by joining two
distinct indices $i$ and $j$ whenever
$|\mathbb{E}[Z_iZ_j]|>\delta=\frac{1}{8}$.
By \eqref{ns_rows}, for every $i$,
\begin{align*}
 K
 \ge\sum_{j=1}^n|\mathbb{E}[Z_iZ_j]|^d
 \ge\delta^d\,
 \#\bigl\{j\ne i:\ |\mathbb{E}[Z_iZ_j]|>\delta\bigr\}.
\end{align*}
Every vertex therefore has degree at most
$K\delta^{-d}=K8^d$.
Then, we can  partition  $\{1,\ldots,n\}$ into at most
$L:=1+\lfloor K8^d\rfloor$ classes, say $C_1,\ldots,C_L$,
such that $|\mathbb{E}[Z_iZ_j]|\le\delta$ for distinct $i,j\in C_\ell$.
Each class inherits \eqref{ns_rows} with the same $K$,
so the separated-coordinate estimate applies within each class.

For each $\ell$, write
$C_\ell=\{k_{\ell,1}<\cdots<k_{\ell,n_\ell}\}$
in the order inherited from $\{1,\ldots,n\}$.
For every $m\in\{0,\ldots,n\}$, the indices of $C_\ell$
lying in $\{1,\ldots,m\}$ form an initial segment
$\{k_{\ell,1},\ldots,k_{\ell,r_\ell(m)}\}$
for some $0\le r_\ell(m)\le n_\ell$.
Hence
\begin{align*}
 \max_{0\le m\le n}
 \left|\sum_{k=1}^m f(Z_k)\right|
 &\le
 \sum_{\ell=1}^L
 \max_{0\le r\le n_\ell}
 \left|\sum_{a=1}^r f(Z_{k_{\ell,a}})\right|.
\end{align*}
Applying the separated-coordinate $L^2$ estimate to each
class, with its own length $n_\ell$, and using
Minkowski's inequality, we obtain
\begin{align*}
 \left\|\max_{0\le m\le n}
 \left|\sum_{k=1}^m f(Z_k)\right|\right\|_2
 \le C_{d,K}\sum_{\ell=1}^L\sqrt{n_\ell}
 \le C_{d,K}\sqrt{L\sum_{\ell=1}^L n_\ell}
 =C_{d,K}\sqrt{Ln}.
\end{align*}
Since $L=1+\lfloor K8^d\rfloor$ depends only on $d$ and $K$,
the factor $\sqrt L$ can be absorbed into the constant.
Hence, the proof is complete.
\qedhere

\label{lat_lem}
Let $h:\mathbb{R}\to[0,\infty)$ be measurable with $h\in L^1(\mathbb{R})$ and
$h(0)<\infty$.
Then, for every \(A>0\),
\begin{align}\label{lat_int}
 \int_A^{2A}\sum_{k\in\mathbb{Z}}h(ak)\,da<\infty.
\end{align}
Consequently, \(\sum_{k\in\mathbb{Z}}h(ak)<\infty\) for almost every
\(a\in[A,2A]\).

By joint measurability, Fubini,  and the standard
normal marginals of $Y$, we have for every finite $R>0$,
\begin{align}\label{01_bdd}
 \mathbb{E}\int_0^R|g(Y(s))|\,ds
 =R\|g\|_1<\infty.
\end{align}
Thus the integrand is locally integrable almost surely,
and the integral paths are continuous.
Moreover, Minkowski's inequality gives
\begin{align}\label{cell_l2}
 \left\|\int_a^b|g(Y(s))|\,ds\right\|_2
 \le\int_a^b\|g(Y(s))\|_2\,ds
 =(b-a)\|g\|_2,
 \quad 0\le a\le b.
\end{align}
If $\varepsilon=1$, then
\begin{align*}
 \sup_{0\le t\le1}|F_1^g(t)|
 =
 \sup_{0\le t\le1}
 \left|\int_0^t g(Y(s))\,ds\right|
 \le\int_0^1|g(Y(s))|\,ds.
\end{align*}
Hence \eqref{cell_l2} yields
\begin{align*}
 \left\|\sup_{0\le t\le1}|F_1^g(t)|\right\|_2
 \le\left\|\int_0^1|g(Y(s))|\,ds\right\|_2
 \le\|g\|_2.
\end{align*}

Assume henceforth that $0<\varepsilon<1$ and put
$N=\lceil1/\varepsilon\rceil-1\ge1$.
For every integer $m\ge0$, decomposing $[1,1+m]$
into unit intervals gives the fiber identity
\begin{align*}
 \int_1^{1+m}g(Y(s))\,ds
 &=
 \sum_{k=0}^{m-1}\int_0^1g(Y(1+u+k))\,du
 =
 \int_0^1\sum_{k=0}^{m-1}g(Y(1+u+k))\,du,
\end{align*}
with the empty sum interpreted as zero.
For each $u\in[0,1]$, the row bound \eqref{ns_fib}
allows us to apply Theorem~\ref{ns_max} with $p=2$
to the corresponding Gaussian fiber.
Taking the maximum inside the integral and then applying
Minkowski's inequality therefore yields
\begin{align}  \label{ns_end}
\begin{aligned}
 \left\|\max_{0\le m\le N}
 \Big|\int_1^{1+m}g(Y(s))\,ds\Big|\right\|_2
 &\le
 \int_0^1
 \left\|\max_{0\le m\le N}
 \Big| \sum_{k=0}^{m-1}g(Y(1+u+k)) \Big|
 \right\|_2\,du \\
 &\quad\le C_{d,K}\sqrt N\,\|g\|_2.
\end{aligned}
\end{align}
Set
$A_k=\int_{1+k}^{2+k}|g(Y(s))|\,ds$ for $0\le k<N$.
By \eqref{cell_l2},
\begin{align}\label{12_bdd}
 \left\|\max_{0\le k<N}A_k\right\|_2
 \le
 \left(\sum_{k=0}^{N-1}\mathbb{E}[A_k^2]\right)^{\frac{1}{2}}
 \le\sqrt N\,\|g\|_2.
\end{align}

To pass from integer endpoints to arbitrary times,
fix $t\in[0,1]$ and put $r=t/\varepsilon$.
If $r\le1$, then
\begin{align*}
 \left|\int_0^r g(Y(s))\,ds\right|
 \le\int_0^1|g(Y(s))|\,ds.
\end{align*}
If $r>1$, set
$m=\lfloor r\rfloor-1$
and
$u=r-(1+m)\in[0,1)$.
Then $r=1+m+u$ and
\begin{align}\label{cell_dec}
 \int_0^r g(Y(s))\,ds
 &=
 \int_0^1g(Y(s))\,ds
 +\int_1^{1+m}g(Y(s))\,ds
+
 \int_{1+m}^{1+m+u}g(Y(s))\,ds.
\end{align}
This separates the initial unit cell, the complete unit cells
ending at $1+m$, and the remaining part of the last cell;
see Figure~\ref{fig_fiber_cells}.
Since $r\le1/\varepsilon\le N+1$, we have $0\le m\le N$.
If $u>0$, necessarily $m<N$, and
\begin{align*}
 \left|\int_{1+m}^{1+m+u}g(Y(s))\,ds\right|
 \le\int_{1+m}^{2+m}|g(Y(s))|\,ds
 =A_m.
\end{align*}
If $u=0$, the last integral in \eqref{cell_dec} vanishes.

