\label{ss_env}
Under the assumptions  \textup{\bf(H.1)} and \textup{\bf(H.2)}  in  Section~\ref{ss_model}, write
$\Phi(s,t)=\mathbb{E}[Y(s)Y(t)]$ and set
\begin{align}\label{kappa_def}
 \kappa=
 \begin{cases}
  \min\{2-\alpha,\nu\},&0<\alpha<1,\\
  2-\alpha,&1\le\alpha<2.
 \end{cases}
\end{align}
Then,  there exists $C<\infty$ such that
\begin{align}\label{ss_envelope}
 |\Phi(s,t)|\le C(1+|t-s|)^{-\kappa},
 \quad s,t\ge1.
\end{align}
In particular, if $\kappa d>1$, then \eqref{ns_fib} holds with a constant
depending only on $X$ and $d$.  The condition $\alpha<2- \frac{1}{d}$ implies
$\kappa d>1$.

\label{ss_critcov}
Under the assumptions of Section~\ref{ss_model}, suppose that
$\alpha=2- \frac{1}{d}$.  For $L\ge2$,
\begin{align}\label{crit_compare}
 \int_0^L\int_0^L
 |\Phi(s,t)^d-a_\alpha(t-s)^d|\,ds\,dt\le CL.
\end{align}
Consequently, for $u,v\ge0$,
\begin{align}\label{crit_covlim}
 \frac{1}{L\log L}\int_0^{Lu}\int_0^{Lv}\Phi(s,t)^d\,ds\,dt
 \longrightarrow
 2A_d^d(u\wedge v),
\end{align}
where $A_d=\frac{(2d-1)(d-1)}{2d^2}$.
When $d=1$, the right-hand side is zero.
